// Build exact 360 distinct systematic improvements across the 6 domains
export const SITE_IMPROVEMENTS_360: SiteImprovement[] = [];

let globalCounter = 1;
DOMAINS.forEach((dom) => {
  dom.topics.forEach((topic, idx) => {
    const code = `${dom.prefix}-${String(idx + 1).padStart(2, '0')}`;
    SITE_IMPROVEMENTS_360.push({
      id: `imp-${globalCounter}`,
      code,
      title: topic.title,
      domain: dom.name,
      categoryNumber: globalCounter,
      problemStatement: topic.problem,
      appliedSolution: topic.solution,
      affectedComponents: dom.components,
      verificationStatus: 'Applied & Verified',
      impactMetric: topic.metric
    });
    globalCounter++;
  });
});

